DIALOGS = [
[anyone, "legate_sq_1_27", [], "Our empire has quite some experience at political scheming, my young friend. And let me tell you that there is no greater threat towards a culture than peaceful assimilation. If reforms and changes are carried out slowly and are enforced only by local conditions, no-one resists. Given enough time, every one of your own kinsmen will give up the elements of culture that made them what they were. ", "legate_sq_1_28", [] ],
]
